// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.authimport android.content.Contextimport androidx.room.Databaseimport androidx.room.Roomimport androidx.room.RoomDatabaseimport androidx.sqlite.db.SupportSQLiteDatabaseimport com.roshan.persona.security.keystore.KeystoreManagerimport dagger.hilt.android.qualifiers.ApplicationContextimport net.sqlcipher.database.SupportFactoryimport timber.log.Timberimport java.security.SecureRandomimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Security Room Database (Module 12, Pillar 3+4). * * Strategy §12.3 / §12.4 — a SQLCipher-encrypted Room database SEPARATE * from `:core:database`'s [com.roshan.persona.database.NousDatabase]. This * avoids schema-versioning coupling between the security module and the * memory module. * * ## Tables * *   - `pin_hash` — [PinHashEntity] (singleton row holding the Argon2id hash *     of the user's app-lock PIN). * * ## Encryption * * The database is encrypted with SQLCipher (AES-256-CBC + HMAC-SHA512 for * integrity). The 32-byte passphrase is: * *   1. Generated once with [SecureRandom] on first launch. *   2. Encrypted with [KeystoreManager] under alias *      [PASSPHRASE_KEY_ALIAS] (AndroidKeystore-backed AES-256-GCM). *   3. Persisted (ciphertext + IV) to a private SharedPreferences file. * * On subsequent launches, the passphrase is decrypted from disk via the * Keystore key and passed to [SupportFactory] which configures the Room * `OpenHelperFactory` for SQLCipher. * * If Keystore decryption fails (e.g., key was invalidated by biometric * enrollment change), we regenerate a fresh passphrase — the PIN hash table * is small (one row), so the user just needs to re-set their PIN. This is * the documented behavior of `pinStorage.isPinSet()` returning `false` after * a key invalidation event. * * ## Real Android APIs used * * | Operation | API | * |-----------|-----| * | SQLCipher factory | `net.sqlcipher.database.SupportFactory(passphrase)` | * | Room builder | `Room.databaseBuilder(context, dbClass, fileName)` | * | Keystore wrap | [KeystoreManager.encryptString] / [decryptString] | * | Secure random | `java.security.SecureRandom` | * * @see PinHashEntity * @see PinHashDao * @see SqlCipherPinStorage */@Database(    entities = [PinHashEntity::class],    version = 1,    exportSchema = true,)abstract class SecurityDatabase : RoomDatabase() {    /** DAO for the [PinHashEntity] table. */    abstract fun pinHashDao(): PinHashDao    companion object {        /** File name for the SQLCipher-encrypted Room DB. */        const val DATABASE_NAME = "nous_security.db"        /** Current schema version. */        const val DATABASE_VERSION = 1    }}/** * Hilt provider for [SecurityDatabase]. * * Singleton-scoped — the Room database instance is shared across the entire * app. The DAO exposed via [SecurityDatabase.pinHashDao] is also effectively * a singleton because Room's DAOs are stateless wrappers around the DB's * internal SQLite connection. */@Singletonclass SecurityDatabaseProvider @Inject constructor(    @ApplicationContext private val context: Context,    private val keystoreManager: KeystoreManager,) {    /** Lazily-constructed [SecurityDatabase] (built on first DAO injection). */    val database: SecurityDatabase by lazy { buildDatabase() }    /** Convenience accessor for the PIN hash DAO. */    fun pinHashDao(): PinHashDao = database.pinHashDao()    private fun buildDatabase(): SecurityDatabase {        val passphrase = resolvePassphrase()        val supportFactory = SupportFactory(passphrase)        return Room.databaseBuilder(            context,            SecurityDatabase::class.java,            SecurityDatabase.DATABASE_NAME,        )            .openHelperFactory(supportFactory)            .fallbackToDestructiveMigrationOnDowngrade()            .addCallback(object : RoomDatabase.Callback() {                override fun onCreate(db: SupportSQLiteDatabase) {                    Timber.tag("NOUS.Security").i("SecurityDatabase created (SQLCipher-encrypted)")                }            })            .build()    }    /**     * Resolve the 32-byte SQLCipher passphrase for the security DB.     *     * - If we already have a passphrase stored (encrypted by Keystore), decrypt it.     * - Otherwise, generate 32 random bytes, wrap with Keystore, persist.     *     * On any failure (Keystore broken, ciphertext corrupted, biometric     * enrollment change invalidating the key), we delete the persisted     * ciphertext and regenerate — this means the PIN row is lost (user     * re-sets PIN), but the app keeps booting instead of crashing.     */    private fun resolvePassphrase(): ByteArray {        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)        val existingCiphertext = prefs.getString(KEY_CIPHERTEXT, null)        val existingIv = prefs.getString(KEY_IV, null)        if (existingCiphertext != null && existingIv != null) {            try {                ensureKey()                val ciphertext = com.roshan.persona.security.keystore.Ciphertext(                    ivBase64 = existingIv,                    ciphertextBase64 = existingCiphertext,                    securityLevel = keystoreManager.lastSecurityLevel(PASSPHRASE_KEY_ALIAS),                )                val decrypted = keystoreManager.decryptString(PASSPHRASE_KEY_ALIAS, ciphertext)                if (decrypted != null) {                    return android.util.Base64.decode(decrypted, android.util.Base64.NO_WRAP)                }                Timber.tag("NOUS.Security").w("SQLCipher passphrase decryption returned null — regenerating")            } catch (e: Exception) {                Timber.tag("NOUS.Security").e(e, "SQLCipher passphrase decryption failed — regenerating")            }            // Decryption failed — clear stale state so we generate fresh.            prefs.edit().remove(KEY_CIPHERTEXT).remove(KEY_IV).apply()        }        // Generate a fresh 32-byte random passphrase.        val randomBytes = ByteArray(32).also { SecureRandom().nextBytes(it) }        ensureKey()        val b64 = android.util.Base64.encodeToString(randomBytes, android.util.Base64.NO_WRAP)        val ciphertext = keystoreManager.encryptString(PASSPHRASE_KEY_ALIAS, b64)        if (ciphertext == null) {            // Keystore encryption failed — fall back to transient key (DB            // unreadable on next launch, but the app boots this session).            Timber.tag("NOUS.Security").w("Keystore wrap failed — using transient SQLCipher passphrase")            return randomBytes        }        prefs.edit()            .putString(KEY_CIPHERTEXT, ciphertext.ciphertextBase64)            .putString(KEY_IV, ciphertext.ivBase64)            .apply()        return randomBytes    }    /** Generate the Keystore key used to wrap the SQLCipher passphrase. */    private fun ensureKey() {        if (!keystoreManager.keyExists(PASSPHRASE_KEY_ALIAS)) {            keystoreManager.generateKey(PASSPHRASE_KEY_ALIAS, requireAuth = false)        }    }    private companion object {        const val PASSPHRASE_KEY_ALIAS = "nous.security.db.passphrase"        const val PREFS_NAME = "nous_security_db_key"        const val KEY_CIPHERTEXT = "passphrase_ciphertext"        const val KEY_IV = "passphrase_iv"    }}